// Worker entry: the Next.js app (built by OpenNext) plus the hourly usage check that emails the owner.
// @ts-ignore generated by `opennextjs-cloudflare build`
import { default as app } from "./.open-next/worker.js";
import { runUsageAlert } from "./src/lib/usageAlert";

export default {
  fetch: app.fetch,
  async scheduled(_event: unknown, env: Parameters<typeof runUsageAlert>[0], ctx: { waitUntil(p: Promise<unknown>): void }) {
    ctx.waitUntil(runUsageAlert(env).catch((e) => console.error("usage alert", e)));
  },
};
